<?php
/**
 * Hand-maintained dependency manifest for edit.js.
 *
 * Normally generated by @wordpress/scripts at build time, but this plugin
 * has no build step. WordPress reads this file when registering the block
 * to know which wp-* packages must be enqueued before edit.js runs.
 * Without it, edit.js loads with no deps and `window.wp` is undefined.
 *
 * Bump `version` whenever edit.js changes meaningfully so browsers bust
 * their cache. Tied to the plugin version constant for simplicity.
 */
return [
	'dependencies' => [
		'wp-blocks',
		'wp-element',
		'wp-block-editor',
		'wp-components',
		'wp-server-side-render',
		'wp-i18n',
	],
	'version'      => '0.2.1',
];
